package com.bct.ngtpa.apiservice.infrastructure.security.session;
import static org.assertj.core.api.Assertions.*;import com.bct.ngtpa.apiservice.application.dto.*;import com.bct.ngtpa.apiservice.application.dto.session.authenticated.*;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class AesGcmAuthenticatedSessionProtectorTest {private final AesGcmAuthenticatedSessionProtector protector=new AesGcmAuthenticatedSessionProtector(Base64.getEncoder().encodeToString(new byte[32]),new ObjectMapper().findAndRegisterModules());
 @Test void roundTripPreservesActorAccountsStatusAndExpiry(){var session=session();var protectedValue=protector.protect(session);assertThat(protectedValue.version()).isEqualTo("v1");assertThat(protectedValue.toString()).doesNotContain("member01","00000008802","csrf_hash");assertThat(protector.unprotect(protectedValue)).isEqualTo(session);}
 @Test void sameSessionUsesFreshNonceAndCiphertext(){var a=protector.protect(session());var b=protector.protect(session());assertThat(a.nonce()).isNotEqualTo(b.nonce());assertThat(a.ciphertext()).isNotEqualTo(b.ciphertext());}
 @Test void tamperingFailsClosedWithoutSecretLeakage(){var p=protector.protect(session());var tampered=new ProtectedAuthenticatedSession(p.version(),p.ciphertext()+"A",p.nonce(),p.authenticationTag());assertThatThrownBy(()->protector.unprotect(tampered)).isInstanceOf(IllegalStateException.class).hasMessage("Unable to unprotect authenticated session").hasMessageNotContaining("member01").hasMessageNotContaining("00000008802").hasMessageNotContaining("csrf_hash");}
 @Test void invalidKeyLengthAndVersionFailClosed(){assertThatThrownBy(()->new AesGcmAuthenticatedSessionProtector(Base64.getEncoder().encodeToString(new byte[16]),new ObjectMapper())).isInstanceOf(IllegalArgumentException.class);var p=protector.protect(session());assertThatThrownBy(()->protector.unprotect(new ProtectedAuthenticatedSession("v2",p.ciphertext(),p.nonce(),p.authenticationTag()))).isInstanceOf(IllegalArgumentException.class);}
 private AuthenticatedSession session(){Instant now=Instant.parse("2026-07-20T00:00:00Z");return new AuthenticatedSession(new AuthenticatedSessionId("sid_abcdefghijklmnopqrstuvwx"),new ActorContext("member01","USER"),List.of(new AuthenticatedSessionAccount(new AuthenticatedAccountRef("acc_abcdefghijklmnopqrstuvwx"),"DB","00000008802","0001","DBA","OE",null,null)),AuthenticatedSessionStatus.ACTIVE,"csrf_hash",now,now,now.plusSeconds(1800),now.plusSeconds(28800));}}
